#!/bin/bash -eu
# Generated by fuzzbench_generate.py for bug transplant evaluation

cd /src/c-blosc2

# Drop stale build artifacts from the merge container so `git checkout`
# is not blocked by untracked files that would be overwritten.
git clean -fdx >/dev/null 2>&1 || true
git reset --hard HEAD >/dev/null 2>&1 || true

# Checkout target commit
git checkout cf8d63c23d68754eb50762b45e58ab9a13b8d470

# Restore harness sources that live outside the project git repository,
# and compute --exclude flags so harness.diff doesn't re-modify files
# that have already been restored to their post-dispatch state by the
# snapshot copy (which would fail with "does not match index").
HARNESS_EXCLUDES=""
if [ -f /src/patches/harness_sources/manifest.json ]; then
    HARNESS_EXCLUDES=$(python3 - <<'PY'
import json
import shutil
from pathlib import Path

root = Path("/src/patches/harness_sources")
manifest = json.loads((root / "manifest.json").read_text())
excludes = []
for entry in manifest:
    source = root / entry["snapshot"]
    destination = Path(entry["container_path"])
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source, destination)
    # Convert /src/<repo>/<rel> to <rel> (git apply paths are repo-relative).
    parts = destination.parts
    if len(parts) >= 3 and parts[1] == "src":
        rel = Path(*parts[3:])
    else:
        rel = destination
    excludes.append(f"--exclude={rel}")
print(" ".join(excludes))
PY
)
fi

# Apply dispatch harness first (modifies build system), then bug patches.
# $HARNESS_EXCLUDES is empty when no snapshots were restored.
if ! git apply --check $HARNESS_EXCLUDES /src/patches/harness.diff 2>/dev/null; then
    echo "Trying git apply --3way for harness.diff..."
    git apply --3way $HARNESS_EXCLUDES /src/patches/harness.diff
else
    git apply $HARNESS_EXCLUDES /src/patches/harness.diff
fi

if ! git apply --check /src/patches/combined.diff 2>/dev/null; then
    echo "Trying git apply --3way for combined.diff..."
    git apply --3way /src/patches/combined.diff
else
    git apply /src/patches/combined.diff
fi

# --- Fix library CMakeLists.txt for new source files from combined.diff ---
# combined.diff may create new .c files (e.g., zfp_getcell.c) that need to
# be added to the library's explicit source list.
if [ -d blosc ] && [ -f blosc/CMakeLists.txt ]; then
    for newfile in blosc/*.c; do
        base=$(basename "$newfile")
        if ! grep -q "$base" blosc/CMakeLists.txt 2>/dev/null; then
            echo "Adding $base to blosc/CMakeLists.txt"
            sed -i "/^set(SOURCES /s/)/ $base)/" blosc/CMakeLists.txt
        fi
    done
fi

# --- Original build commands ---
export LDSHARED=lld

cmake . -DCMAKE_C_FLAGS="$CFLAGS" -DCMAKE_CXX_FLAGS="$CXXFLAGS" -DBUILD_FUZZERS=ON -DBUILD_TESTS=OFF -DBUILD_BENCHMARKS=OFF -DBUILD_EXAMPLES=OFF
make clean
make -j$(nproc) -k 2>&1 || true

# Package seed corpus
zip -j $OUT/decompress_chunk_fuzzer_seed_corpus.zip compat/*.cdata
zip -j $OUT/decompress_frame_fuzzer_seed_corpus.zip tests/fuzz/corpus/*

# Copy the fuzzer executables, zip-ed corpora, and dictionary files to $OUT
find . -name '*_fuzzer' -exec cp -v '{}' $OUT ';'
find . -name '*_fuzzer.dict' -exec cp -v '{}' $OUT ';'
find . -name '*_fuzzer_seed_corpus.zip' -exec cp -v '{}' $OUT ';'


# --- Seed corpus: expand original seeds and per-bug testcase candidates ---
# FuzzBench uses $OUT/{fuzz_target}_seed_corpus.zip as initial corpus.
# Create one seed variant for the default path plus one for each dispatch bit.
# Per-bug reproducers are used only as source material: exact crashing inputs
# are filtered out before packaging.
seed_zip="$OUT/decompress_frame_fuzzer_seed_corpus.zip"
seed_target="$OUT/decompress_frame_fuzzer"
mkdir -p /tmp/seeds_dispatch /tmp/original_seeds

if [ -f "$seed_zip" ]; then
    unzip -q -o "$seed_zip" -d /tmp/original_seeds 2>/dev/null || true
    for f in /tmp/original_seeds/*; do
        [ -f "$f" ] || continue
        base=$(basename "$f")
        for dispatch in '\x00' '\x0c' '\x14' '\x1c' '\x24' '\x2c' '\x34' '\x3c' '\x44' '\x4c' '\x54' '\x5c' '\x64' '\x6c' '\x74' '\x7c' '\x84' '\x8c' '\x94' '\x9c' '\xa4' '\xac' '\xb4' '\xbc' '\xc4' '\xcc' '\xd4' '\xdc' '\xe4' '\xec'; do
            dispatch_name=$(printf '%s' "$dispatch" | tr -d '\x')
            printf '%b' "$dispatch" | cat - "$f" > "/tmp/seeds_dispatch/${base}.dispatch_${dispatch_name}"
        done
    done
fi

# Initial corpus: the project's public ClusterFuzz corpus, already
# dispatch-zero prefixed (head byte 0x00 = slot 0 = no bug) and
# crash-filtered. Fuzzers must mutate the selector byte themselves to reach
# any gated bug, so no seed opens a bug's gate. PoC derivatives are NOT used.
for _z in /src/corpus_seeds*.zip; do
    [ -f "$_z" ] || continue
    echo "Unpacking initial corpus: $_z"
    unzip -q -o "$_z" -d /tmp/seeds_dispatch
done

# Avoid ARG_MAX: a glob over a large corpus silently fails and the seed zip
# never gets written, leaving fuzzers with a fake 2-byte seed.
if [ -n "$(find /tmp/seeds_dispatch -maxdepth 1 -type f -print -quit 2>/dev/null)" ]; then
    rm -f "$seed_zip"
    find /tmp/seeds_dispatch -maxdepth 1 -type f -print0 | xargs -0 zip -j -q "$seed_zip"
fi
